def vertex_cover(n, edges):
    cover = set()
    used = [False] * len(edges)
    for i, (u, v) in enumerate(edges):
        if not used[i]:
            cover.add(u)
            cover.add(v)
            for j in range(i, len(edges)):
                eu, ev = edges[j]
                if eu in (u, v) or ev in (u, v):
                    used[j] = True
    return sorted(cover)

