bool solve(vector<vector<int>>& adj, int n, int k, int v) {
    if (v == n) return true;
    for (int c = 1; c <= k; c++) {
        if (isSafe(adj, v, c)) {
            color[v] = c;
            if (solve(adj, n, k, v + 1)) return true;
            color[v] = 0;
        }
    }
    return false;
}
