def can_color(adj, n, k):
    color = [0] * n
    def is_safe(v, c):
        return all(color[u] != c for u in adj[v])
    def solve(v):
        if v == n:
            return True
        for c in range(1, k + 1):
            if is_safe(v, c):
                color[v] = c
                if solve(v + 1):
                    return True
                color[v] = 0
        return False
    return solve(0)

