pair<int, vector<int>> tspNearestNeighbor(vector<vector<int>>& dist, int n) {
    vector<bool> visited(n, false);
    vector<int> path = {0};
    visited[0] = true;
    int total = 0, curr = 0;
    for (int i = 1; i < n; i++) {
        int nearest = -1, minD = INT_MAX;
        for (int j = 0; j < n; j++) {
            if (!visited[j] && dist[curr][j] < minD) {
                minD = dist[curr][j]; nearest = j;
            }
        }
        visited[nearest] = true;
        total += minD;
        path.push_back(nearest);
        curr = nearest;
    }
    total += dist[curr][0];
    path.push_back(0);
    return {total, path};
}

