string solveSAT(int n, vector<vector<int>>& clauses) {
    for (int mask = 0; mask < (1 << n); mask++) {
        bool allSat = true;
        for (auto& clause : clauses) {
            bool clauseSat = false;
            for (int lit : clause) {
                int var = abs(lit) - 1;
                bool val = (mask >> var) & 1;
                if (lit > 0 && val) clauseSat = true;
                if (lit < 0 && !val) clauseSat = true;
            }
            if (!clauseSat) { allSat = false; break; }
        }
        if (allSat) {
            string result = "SATISFIABLE\n";
            for (int i = 0; i < n; i++) {
                if (i > 0) result += " ";
                result += ((mask >> i) & 1) ? to_string(i+1) : "-" + to_string(i+1);
            }
            return result;
        }
    }
    return "UNSATISFIABLE";
}

