def solve_sat(n, clauses):
    for mask in range(1 << n):
        assignment = [(mask >> i) & 1 for i in range(n)]
        all_sat = True
        for clause in clauses:
            clause_sat = False
            for lit in clause:
                var = abs(lit) - 1
                if lit > 0 and assignment[var] == 1:
                    clause_sat = True
                if lit < 0 and assignment[var] == 0:
                    clause_sat = True
            if not clause_sat:
                all_sat = False
                break
        if all_sat:
            result = []
            for i in range(n):
                result.append(i+1 if assignment[i] else -(i+1))
            return (True, result)
    return (False, None)
